TRAP, TABLE, N = 0x70, 0x2d0, 56
FUNCS = {0x140: 0x28, 0x148: 0x54, 0x150: 0x18, 0x158: 0x20}   # slot -> code offset (rgen, runi, ctxsz, kinit)

def br(frm, to, link=False):
    off = (to - frm) >> 2
    assert -(1 << 25) <= off < (1 << 25)
    return (0x94000000 if link else 0x14000000) | (off & 0x3FFFFFF)

def main():
    k = bytearray(open(sys.argv[1], 'rb').read())
    if len(k) != SIZE: sys.exit(f'size {len(k)} != {SIZE}')
    rd = lambda va: struct.unpack_from('<I', k, va - BASE)[0]
    if rd(SITE) != RET: sys.exit(f'{SITE:#x} is not ret (canary/trace already applied?)')
    if rd(HALT) != 0x14000000: sys.exit('M3E tail is not halted: apply halt_tail.py first')
    end = VA + TABLE + 8 * N
    for va in range(VA - 4, end + 4, 4):
        if rd(va) != NOP: sys.exit(f'{va:#x} not NOP (hole in use)')
    blob = bytearray(CODE)
    struct.pack_into('<I', blob, 0xc, br(VA + 0xc, REG, True))
    struct.pack_into('<I', blob, 0x27c, br(VA + 0x27c, HALT))
    for i in range(N):
        blob += struct.pack('<Q', VA + FUNCS.get(i * 8, TRAP + 8 * i))
    k[VA - BASE:VA - BASE + len(blob)] = blob
    struct.pack_into('<I', k, SITE - BASE, br(SITE, VA))
    open(sys.argv[2], 'wb').write(k)
    print(f'crypto_reg: ret@{SITE:#x} -> {VA:#x}; table @{VA + TABLE:#x} ({N} slots, 4 live); {len(blob)} B')

if __name__ == '__main__':
    main()
